const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define the two locations in Norwegian Sea
  const loc1 = ee.Geometry.Point([-58.944881, 50.282684]);
  const loc2 = ee.Geometry.Point([-54.128047, 50.415337]);

  // Time period: September 1, 2019 ± 5 days for cloud-free image
  const startDate = '2019-08-27';
  const endDate = '2019-09-05';

  // Sentinel-2 MSI collection
  let col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(startDate, endDate)
    .filterBounds(loc1.buffer(50000))
    .filterMetadata('CLOUDY_PIXEL_PERCENTAGE', 'less_than', 50);

  const colSize = col.size().getInfo();
  console.log(`Sentinel-2 images found: ${colSize}`);

  if (colSize === 0) {
    console.log('No data available for September 1, 2019');
    console.log('C1');
    return;
  }

  // Cloud mask function (QA60)
  function maskClouds(img) {
    const qa = img.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    return img.updateMask(qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0)))
      .divide(10000); // Scale reflectance
  }

  // Get median composite (best available)
  const composite = col.map(maskClouds).median();

  // Turbidity index: (Red + Green) / Blue (higher = milkier/more suspended matter)
  // Using B4 (Red), B3 (Green), B2 (Blue)
  const turbidityIndex = composite.select('B4').add(composite.select('B3'))
    .divide(composite.select('B2'));

  // Calculate turbidity at location 1
  const stats1 = turbidityIndex.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: loc1,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const pixelCount1 = composite.select('B2').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: loc1,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const turbidity1 = stats1['B4'] !== undefined ? stats1['B4'] : null;
  const count1 = pixelCount1['B2'] || 0;

  console.log(`Location 1 (${-58.944881}, ${50.282684}): Turbidity=${turbidity1 !== null ? turbidity1.toFixed(3) : 'N/A'}, Pixels=${count1}`);

  // Calculate turbidity at location 2
  const stats2 = turbidityIndex.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: loc2,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const pixelCount2 = composite.select('B2').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: loc2,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const turbidity2 = stats2['B4'] !== undefined ? stats2['B4'] : null;
  const count2 = pixelCount2['B2'] || 0;

  console.log(`Location 2 (${-54.128047}, ${50.415337}): Turbidity=${turbidity2 !== null ? turbidity2.toFixed(3) : 'N/A'}, Pixels=${count2}`);

  // Validation
  if (count1 === 0 || count2 === 0) {
    console.log('No valid pixels after cloud masking at one or both locations');
    console.log('C2');
    return;
  }

  if (turbidity1 === null || turbidity2 === null || isNaN(turbidity1) || isNaN(turbidity2)) {
    console.log('Calculation failure: invalid turbidity values');
    console.log('C3');
    return;
  }

  // Compare: Location 1 more milky than Location 2?
  const isMoreMilky = turbidity1 > turbidity2;

  console.log(`Turbidity comparison: ${turbidity1.toFixed(3)} vs ${turbidity2.toFixed(3)}`);
  console.log(isMoreMilky ? 'A' : 'B');
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
